package com.example.csvexport.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDate;

@Entity
@Table(name = "employees")
public class Employee {

    @Id
    @Column(name = "emp_id", length = 6)
    private String empId;

    @Column(name = "emp_name", length = 30)
    private String empName;

    @Column(name = "emp_dept", length = 20)
    private String empDept;

    @Column(name = "emp_salary", precision = 9, scale = 2)
    private BigDecimal empSalary;

    @Column(name = "emp_hire_date")
    private LocalDate empHireDate;

    @Column(name = "emp_age")
    private Integer empAge;

    public Employee() {}

    public Employee(String empId, String empName, String empDept,
                    BigDecimal empSalary, LocalDate empHireDate, Integer empAge) {
        this.empId = empId;
        this.empName = empName;
        this.empDept = empDept;
        this.empSalary = empSalary;
        this.empHireDate = empHireDate;
        this.empAge = empAge;
    }

    public String getEmpId()           { return empId; }
    public void setEmpId(String v)     { this.empId = v; }

    public String getEmpName()         { return empName; }
    public void setEmpName(String v)   { this.empName = v; }

    public String getEmpDept()         { return empDept; }
    public void setEmpDept(String v)   { this.empDept = v; }

    public BigDecimal getEmpSalary()        { return empSalary; }
    public void setEmpSalary(BigDecimal v)  { this.empSalary = v; }

    public LocalDate getEmpHireDate()       { return empHireDate; }
    public void setEmpHireDate(LocalDate v) { this.empHireDate = v; }

    public Integer getEmpAge()         { return empAge; }
    public void setEmpAge(Integer v)   { this.empAge = v; }
}

