package com.example.csvexport.service;

import com.example.csvexport.model.Employee;
import com.example.csvexport.repository.EmployeeRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.io.BufferedWriter;
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.List;

/**
 * CsvExportService
 *
 * Faithfully reproduces the business logic of COBOL program CSVEXPRT:
 *   - Opens output CSV file
 *   - Writes a header line:  id,name,department,salary,hire_date,age
 *   - Iterates every employee record (equivalent to the READ loop)
 *   - For each record formats salary as Z(06)9.99 and age as Z9,
 *     then builds a comma-separated line and writes it
 *   - Logs the total count of exported records
 */
@Service
public class CsvExportService {

    private static final Logger log = LoggerFactory.getLogger(CsvExportService.class);

    /** CSV header – mirrors the COBOL literal exactly */
    private static final String CSV_HEADER = "id,name,department,salary,hire_date,age";

    private final EmployeeRepository employeeRepository;

    /** Output path, overridable via application.properties */
    @Value("${csvexport.output-path:data/output/employees.csv}")
    private String outputPath;

    public CsvExportService(EmployeeRepository employeeRepository) {
        this.employeeRepository = employeeRepository;
    }

    /**
     * Main export method – equivalent to MAIN-PARA in CSVEXPRT.
     *
     * @return number of records exported (WS-COUNT)
     */
    @Transactional(readOnly = true)
    public int exportToCsv() throws IOException {

        // Ensure parent directories exist (equivalent to OPEN OUTPUT CSV-FILE)
        Path csvPath = Paths.get(outputPath);
        if (csvPath.getParent() != null) {
            Files.createDirectories(csvPath.getParent());
        }

        int wsCount = 0; // WS-COUNT PIC 9(03) VALUE 0

        // Fetch all employees – replaces the PERFORM UNTIL END-OF-FILE / READ loop
        List<Employee> employees = employeeRepository.findAll();

        try (BufferedWriter writer = Files.newBufferedWriter(
                csvPath, StandardCharsets.UTF_8,
                StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {

            // MOVE "id,name,..." TO CSV-LINE / WRITE CSV-LINE
            writer.write(CSV_HEADER);
            writer.newLine();

            for (Employee emp : employees) {
                // PERFORM WRITE-CSV
                String csvLine = buildCsvLine(emp);
                writer.write(csvLine);
                writer.newLine();
                wsCount++; // ADD 1 TO WS-COUNT
            }
        }

        // DISPLAY "CSVEXPRT: " WS-COUNT " RECORDS EXPORTED"
        log.info("CSVEXPRT: {} RECORDS EXPORTED", String.format("%03d", wsCount));
        return wsCount;
    }

    // ----------------------------------------------------------------
    // WRITE-CSV paragraph
    // ----------------------------------------------------------------

    /**
     * Builds a single CSV line for one employee record.
     *
     * Mirrors the COBOL STRING statement exactly:
     *   EMP-ID , TRIM(EMP-NAME) , TRIM(EMP-DEPT) , TRIM(WS-SALARY-ED)
     *   , EMP-HIRE-YYYY "-" EMP-HIRE-MM "-" EMP-HIRE-DD , TRIM(WS-AGE-ED)
     */
    String buildCsvLine(Employee emp) {

        // MOVE EMP-SALARY TO WS-SALARY-ED  (PIC Z(06)9.99)
        String salaryEdited = formatSalary(emp.getEmpSalary());

        // MOVE EMP-AGE TO WS-AGE-ED  (PIC Z9)
        String ageEdited = formatAge(emp.getEmpAge());

        // EMP-HIRE-YYYY "-" EMP-HIRE-MM "-" EMP-HIRE-DD
        String hireDate = formatHireDate(emp.getEmpHireDate());

        // STRING ... INTO CSV-LINE (spaces trimmed via FUNCTION TRIM)
        StringBuilder sb = new StringBuilder();
        sb.append(trimCobol(emp.getEmpId()));
        sb.append(',');
        sb.append(trimCobol(emp.getEmpName()));
        sb.append(',');
        sb.append(trimCobol(emp.getEmpDept()));
        sb.append(',');
        sb.append(trimCobol(salaryEdited));   // FUNCTION TRIM(WS-SALARY-ED)
        sb.append(',');
        sb.append(hireDate);                  // concatenation, no trim
        sb.append(',');
        sb.append(trimCobol(ageEdited));      // FUNCTION TRIM(WS-AGE-ED)

        // CSV-LINE is PIC X(100) – truncate if the result exceeds 100 characters
        String result = sb.toString();
        if (result.length() > 100) {
            result = result.substring(0, 100);
        }
        return result;
    }

    // ----------------------------------------------------------------
    // Picture-clause formatters
    // ----------------------------------------------------------------

    /**
     * WS-SALARY-ED  PIC Z(06)9.99
     *
     * Total picture positions: Z Z Z Z Z Z 9 . 9 9  = 10 chars (excl. decimal point = 9 digits + dot)
     * The Z(06) suppresses leading zeros in the first 6 digit positions;
     * the trailing 9.99 always prints.
     *
     * Example:  12345.67  →  "     12345.67"
     *           1234567.89 → "1234567.89"  (7-integer digit, overflow kept)
     */
    static String formatSalary(BigDecimal salary) {
        if (salary == null) {
            salary = BigDecimal.ZERO;
        }
        // Scale to 2 decimal places, matching PIC 9.99
        BigDecimal scaled = salary.setScale(2, java.math.RoundingMode.HALF_UP);

        // Split into integer and fractional parts
        long intPart = scaled.longValue();             // integer portion
        int fracPart = scaled.remainder(BigDecimal.ONE)
                             .abs()
                             .movePointRight(2)
                             .intValue();              // 0-99

        // The picture has 7 integer digits total (Z*6 + one 9)
        // Z(06)9 means positions 1-6 are zero-suppressed, position 7 always prints
        String intStr = String.format("%07d", Math.abs(intPart));
        // Apply zero suppression to first 6 digits (Z(06))
        String suppressed = applyZeroSuppression(intStr, 6);

        String fracStr = String.format("%02d", fracPart);
        return suppressed + "." + fracStr;
    }

    /**
     * WS-AGE-ED  PIC Z9
     *
     * 2 digit picture: first position is Z (zero-suppressed), second is always printed.
     * Example:  5  → " 5"
     *          25  → "25"
     */
    static String formatAge(Integer age) {
        if (age == null) age = 0;
        String s = String.format("%02d", Math.abs(age));
        return applyZeroSuppression(s, 1); // suppress only the leading digit
    }

    /**
     * Applies COBOL Z (zero-suppression) to the first {@code zCount} character
     * positions of a zero-padded numeric string: leading zeros become spaces.
     * The suppression stops as soon as a non-zero digit is encountered.
     *
     * @param padded   zero-padded numeric string (all digit characters)
     * @param zCount   number of leading positions that carry the Z picture
     * @return         string with leading zeros in the Z zone replaced by spaces
     */
    static String applyZeroSuppression(String padded, int zCount) {
        char[] chars = padded.toCharArray();
        boolean significant = false;
        for (int i = 0; i < zCount && i < chars.length; i++) {
            if (!significant && chars[i] == '0') {
                chars[i] = ' ';
            } else {
                significant = true;
            }
        }
        return new String(chars);
    }

    /**
     * Formats the hire date as YYYY-MM-DD, mirroring the COBOL concatenation:
     *   EMP-HIRE-YYYY "-" EMP-HIRE-MM "-" EMP-HIRE-DD
     */
    static String formatHireDate(java.time.LocalDate date) {
        if (date == null) return "0000-00-00";
        return String.format("%04d-%02d-%02d",
                date.getYear(), date.getMonthValue(), date.getDayOfMonth());
    }

    /**
     * COBOL FUNCTION TRIM – removes leading and trailing spaces.
     * Equivalent to Java String.trim() for space-padded fixed-width fields.
     */
    static String trimCobol(String s) {
        return s == null ? "" : s.trim();
    }
}

