package com.example.csvexport.controller;

import com.example.csvexport.service.CsvExportService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.io.IOException;
import java.util.Map;

/**
 * REST endpoint that triggers the CSV export, replacing the
 * batch-style STOP RUN entry point of the original COBOL program.
 */
@RestController
@RequestMapping("/api/v1/export")
public class CsvExportController {

    private final CsvExportService csvExportService;

    public CsvExportController(CsvExportService csvExportService) {
        this.csvExportService = csvExportService;
    }

    /**
     * POST /api/v1/export/csv
     * Triggers employee CSV export and returns the count of exported records.
     */
    @PostMapping("/csv")
    public ResponseEntity<Map<String, Object>> exportCsv() {
        try {
            int count = csvExportService.exportToCsv();
            return ResponseEntity.ok(Map.of(
                    "status", "SUCCESS",
                    "message", String.format("CSVEXPRT: %03d RECORDS EXPORTED", count),
                    "recordsExported", count
            ));
        } catch (IOException ex) {
            return ResponseEntity.internalServerError().body(Map.of(
                    "status", "ERROR",
                    "message", ex.getMessage()
            ));
        }
    }
}

