package com.example.csvexport.runner;

import com.example.csvexport.service.CsvExportService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Component;

/**
 * Optional batch-style runner that mimics the STOP RUN behaviour of the
 * original COBOL program when csvexport.batch-mode=true is set.
 */
@Component
@ConditionalOnProperty(name = "csvexport.batch-mode", havingValue = "true")
public class CsvExportRunner implements ApplicationRunner {

    private static final Logger log = LoggerFactory.getLogger(CsvExportRunner.class);

    private final CsvExportService csvExportService;

    public CsvExportRunner(CsvExportService csvExportService) {
        this.csvExportService = csvExportService;
    }

    @Override
    public void run(ApplicationArguments args) throws Exception {
        log.info("CSVEXPRT: Starting batch CSV export");
        csvExportService.exportToCsv();
    }
}

