package com.example.csvexport.service;

import com.example.csvexport.model.Employee;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.time.LocalDate;

import static org.assertj.core.api.Assertions.assertThat;

class CsvExportServiceTest {

    private final CsvExportService service = new CsvExportService(null);

    // ----------------------------------------------------------
    // formatSalary – PIC Z(06)9.99
    // ----------------------------------------------------------

    @Test
    void salary_small_value_leading_zeros_suppressed() {
        // 12345.67 → "     12345.67"  (5 suppressed zeros in Z zone)
        String result = CsvExportService.formatSalary(new BigDecimal("12345.67"));
        assertThat(result).isEqualTo("     12345.67");
    }

    @Test
    void salary_zero_value() {
        // 0.00 → "      0.00"  (6 suppressed zeros, last '9' position prints 0)
        String result = CsvExportService.formatSalary(BigDecimal.ZERO);
        assertThat(result).isEqualTo("      0.00");
    }

    @Test
    void salary_max_value_no_suppression() {
        // 9999999.99 → "9999999.99"
        String result = CsvExportService.formatSalary(new BigDecimal("9999999.99"));
        assertThat(result).isEqualTo("9999999.99");
    }

    // ----------------------------------------------------------
    // formatAge – PIC Z9
    // ----------------------------------------------------------

    @Test
    void age_single_digit_suppressed() {
        // 5 → " 5"
        assertThat(CsvExportService.formatAge(5)).isEqualTo(" 5");
    }

    @Test
    void age_two_digits_no_suppression() {
        // 42 → "42"
        assertThat(CsvExportService.formatAge(42)).isEqualTo("42");
    }

    @Test
    void age_zero() {
        // 0 → " 0"
        assertThat(CsvExportService.formatAge(0)).isEqualTo(" 0");
    }

    // ----------------------------------------------------------
    // buildCsvLine – full STRING paragraph
    // ----------------------------------------------------------

    @Test
    void buildCsvLine_produces_correct_format() {
        Employee emp = new Employee(
                "EMP001",
                "John Smith         ",   // padded like fixed-width field
                "ACCOUNTING          ",
                new BigDecimal("55000.00"),
                LocalDate.of(2018, 3, 15),
                35
        );

        String line = service.buildCsvLine(emp);

        // id
        assertThat(line).startsWith("EMP001,");
        // name trimmed
        assertThat(line).contains(",John Smith,");
        // dept trimmed
        assertThat(line).contains(",ACCOUNTING,");
        // salary formatted Z(06)9.99 and trimmed
        assertThat(line).contains(",55000.00,");
        // hire date
        assertThat(line).contains(",2018-03-15,");
        // age PIC Z9, trimmed
        assertThat(line).endsWith(",35");
    }

    @Test
    void buildCsvLine_does_not_exceed_100_chars() {
        Employee emp = new Employee(
                "999999",
                "A".repeat(30),
                "B".repeat(20),
                new BigDecimal("9999999.99"),
                LocalDate.of(2024, 12, 31),
                99
        );
        String line = service.buildCsvLine(emp);
        assertThat(line.length()).isLessThanOrEqualTo(100);
    }

    // ----------------------------------------------------------
    // formatHireDate
    // ----------------------------------------------------------

    @Test
    void hireDate_formatted_correctly() {
        assertThat(CsvExportService.formatHireDate(LocalDate.of(2000, 1, 5)))
                .isEqualTo("2000-01-05");
    }

    @Test
    void hireDate_null_returns_placeholder() {
        assertThat(CsvExportService.formatHireDate(null)).isEqualTo("0000-00-00");
    }
}

